head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[dataList > M > setBroadcast]<br/>DataList 모듈의 데이터 변경 내용을 바인드된 컴포넌트에 즉시 반영할지 여부를 설정합니다.",
    "validation" : [
        "DataList 모듈에서 대용량의 데이터가 변경될때 불필요한 화면 갱신을 막아 성능을 향상시킵니다.",
        "broadCast(필수) 파라미터로 DataList 모듈의 변경 내용을 바인드된 컴포넌트에 반영할지 여부를 true/false 로 설정합니다.",
        "broadCast(필수) 파라미터로 true 설정 시 DataList 모듈의 변경 내용을 바인드된 컴포넌트에 즉시 반영합니다.",
        "broadCast(필수) 파라미터로 false 설정 시 DataList 모듈의 변경 내용을 바인드된 컴포넌트에 반영하지 않고, 화면도 갱신되지 않습니다.",
        "refresh(필수) 파라미터로 setBroadcast() 메소드가 실행될때 DataList 모듈의 지난 변경 내용을 바인드된 컴포넌트에 반영할지 여부를 true/false 로 설정합니다.",
        "refresh(필수) 파라미터로 true 설정 시 DataList 모듈의 지난 변경 내용을 바인드된 컴포넌트에 함께 반영합니다.",
        "refresh(필수) 파라미터로 false 설정 시 DataList 모듈의 지난 변경 내용을 바인드된 컴포넌트에 반영하지 않습니다.",
        "broadCast 파라미터값이 false 이면 refresh 파라미터는 false 로 적용됩니다.",
        "refresh 파라미터값은 저장되지 않으며 setBroadcast() 메소드가 실행될때 지난 변경사항을 바인드된 컴포넌트에 반영할지 설정하는 파라미터입니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {   
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        $p.data.remove("target1");
    }

    if (typeof gridView1 !== 'undefined') {
        gridView1.remove();
    }    

    // // 조건 설정       
    // let properties = {

    // };

    // let cList = $c.gcm.createCList(properties);

    // // 이벤트 설정
    // let eList = $c.gcm.createEList([""]);

    // target 생성
    $c.gcm.createBasicDataList();

    // gridView 생성
    $c.gcm.createBasicGridView('dataList="data:target1" rowStatusVisible="true"', '', 'gridView1');
}   



// scwin.btn_insertRow_onclick = function (e) {
//     target1.insertRow();
// };



// scwin.btn_deleteRow_onclick = function (e) {
//     target1.deleteRow(0);
// };



scwin.btn_getGridViewData_onclick = function (e) {
    let gridBodyElem = document.querySelector('tbody[id*="gridView1_body_tbody"]');

    wf_body_bottom.getObj("scwin").setReturnValue("gridView1 text : " + gridBodyElem.textContent);
}



scwin.btn_setBroadcast_onclick = function (e) {
    let broadCast = par_broadCast.getText();

    if (broadCast == "true")
        broadCast = true;
    else if (broadCast == "false")
        broadCast = false;
    else
        broadCast = null;

    let refresh = par_refresh.getText();

    if (refresh == "true")
        refresh = true;
    else if (refresh == "false")
        refresh = false;
    else
        refresh = null;

	target1.setBroadcast(broadCast, refresh);

    scwin.btn_getGridViewData_onclick();
};



scwin.btn_setCellData_onclick = function (e) {
	target1.setCellData(0, "col1", "change1");
    target1.setCellData(1, "col2", "change2");
    target1.setCellData(2, "col3", "change3");
    target1.setCellData(3, "col4", "change4");

    scwin.btn_getGridViewData_onclick();
};
